    """
    Given the routes, yields the following information:

    - path
        eg: /users/
    - http_method
        one of 'get', 'post', 'put', 'patch', 'delete', 'options'
    - func
        method ready to extract the docstring
    """
    endpoints_info: list[EndpointInfo] = []

    for route in routes:
        if isinstance(route, (Mount, Host)):
            if isinstance(route, Mount):
                path = self._remove_converter(route.path)
            else:
                path = ""

            # Handle nested routes in Mount/Host
            if hasattr(route, 'routes') and route.routes is not None:
                sub_endpoints = self.get_endpoints(route.routes)
                for sub_endpoint in sub_endpoints:
                    endpoints_info.append(EndpointInfo(
                        path="".join((path, sub_endpoint.path)),
                        http_method=sub_endpoint.http_method,
                        func=sub_endpoint.func,
                    ))
        elif isinstance(route, Route) and route.include_in_schema:
            if inspect.isfunction(route.endpoint) or inspect.ismethod(route.endpoint):
                path = self._remove_converter(route.path)
                for method in route.methods or ["GET"]:
                    if method == "HEAD":
                        continue
                    endpoints_info.append(EndpointInfo(path, method.lower(), route.endpoint))
